actions.script:
                def anetUrl = pgan.transactionUrl
                def login = pgan.login
                def tranKey = pgan.tranKey
                def want = orderId.toString()
                def successSet = ['authorizedPendingCapture','capturedPendingSettlement','settledSuccessfully'] as Set
                def negativeSet = ['declined','generalError','communicationError','voided','expired','failedReview'] as Set
                def belongs = { String inv -> inv != null && (inv == want ||
                        (inv.startsWith(want + '-') && inv.substring(want.length() + 1) ==~ /\d{1,3}/)) }
                def classify = { String st -> successSet.contains(st) ? 'success' : (negativeSet.contains(st) ? 'negative' : 'uncertain') }
                def rowsById = new LinkedHashMap()
                def collect = { txns ->
                    txns.each { t ->
                        def inv = t.invoiceNumber.text()
                        if (!belongs(inv)) return
                        def st = t.transactionStatus.text()
                        rowsById[t.transId.text()] = [transId: t.transId.text(), invoiceNumber: inv, status: st ?: null,
                                submitTimeUTC: t.submitTimeUTC.text() ?: null, cls: classify(st)]
                    }
                }
                def haveSuccess = { rowsById.values().any { it.cls == 'success' } }
                def complete = (lookupMode != 'routine')
                def pageLimit = 1000
                def hardCap = 20000  // safety ceiling; hitting it makes the scan incomplete
                def run = { String xml -> ec.resource.script('component://AuthorizeDotNet/service/AuthorizeDotNet/HostedHttp.groovy', 'parseHostedXml',
                        [xmlPayload: ec.resource.script('component://AuthorizeDotNet/service/AuthorizeDotNet/HostedHttp.groovy', 'postHostedXml', [targetUrl:anetUrl, xmlPayload:xml])]) }
                def ok = { node -> 'Ok'.equalsIgnoreCase(node.messages?.resultCode?.text() ?: '') }

                // --- 1) Unsettled list, paginated. Routine reads exactly one page. ---
                def offset = 1
                def scanned = 0
                def stop = false
                while (!stop && scanned < hardCap && (lookupMode != 'routine' || gatewayCallCount == 0)) {
                    def listReq = """<?xml version="1.0" encoding="utf-8"?>
<getUnsettledTransactionListRequest xmlns="AnetApi/xml/v1/schema/AnetApiSchema.xsd">
    <merchantAuthentication><name>${encodeForXmlAttribute(login)}</name><transactionKey>${encodeForXmlAttribute(tranKey)}</transactionKey></merchantAuthentication>
    <sorting><orderBy>submitTimeUTC</orderBy><orderDescending>true</orderDescending></sorting>
    <paging><limit>${pageLimit}</limit><offset>${offset}</offset></paging>
</getUnsettledTransactionListRequest>"""
                    gatewayCallCount++
                    ec.logger.log('info', "HOSTED_CONFIRM_GATEWAY_CALL mode=${lookupMode} operation=unsettled call_count=${gatewayCallCount}", null)
                    def listNode = run(listReq)
                    if (!ok(listNode)) { complete = false; break }
                    def txns = listNode.transactions.transaction
                    collect(txns)
                    def total = (listNode.totalNumInResultSet?.text() ?: '0') as Integer
                    scanned += txns.size()
                    if (stopOnSuccess && haveSuccess()) { stop = true; complete = false; break }
                    if (txns.size() < pageLimit || scanned >= total) break
                    if (scanned >= hardCap) { complete = false; break }
                    offset += pageLimit
                }

                // --- 2) Recent settled batches (recovery only; skipped once a success ends a stopOnSuccess scan). ---
                if (lookupMode != 'routine' && !stop && !(stopOnSuccess && haveSuccess())) {
                    def nowUtc = java.time.Instant.now()
                    def firstUtc = nowUtc.minus(java.time.Duration.ofDays(30))
                    def fmt = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss'Z'").withZone(java.time.ZoneOffset.UTC)
                    def batchReq = """<?xml version="1.0" encoding="utf-8"?>
<getSettledBatchListRequest xmlns="AnetApi/xml/v1/schema/AnetApiSchema.xsd">
    <merchantAuthentication><name>${encodeForXmlAttribute(login)}</name><transactionKey>${encodeForXmlAttribute(tranKey)}</transactionKey></merchantAuthentication>
    <firstSettlementDate>${fmt.format(firstUtc)}</firstSettlementDate>
    <lastSettlementDate>${fmt.format(nowUtc)}</lastSettlementDate>
</getSettledBatchListRequest>"""
                    gatewayCallCount++
                    ec.logger.log('info', "HOSTED_CONFIRM_GATEWAY_CALL mode=${lookupMode} operation=settled_batches call_count=${gatewayCallCount}", null)
                    def batchNode = run(batchReq)
                    if (!ok(batchNode)) { complete = false }
                    else {
                        def batchIds = batchNode.batchList.batch.collect { it.batchId.text() }
                        for (bid in batchIds.reverse()) {
                            if (stopOnSuccess && haveSuccess()) { complete = false; break }
                            def boff = 1
                            def bscanned = 0
                            while (true) {
                                def tlReq = """<?xml version="1.0" encoding="utf-8"?>
<getTransactionListRequest xmlns="AnetApi/xml/v1/schema/AnetApiSchema.xsd">
    <merchantAuthentication><name>${encodeForXmlAttribute(login)}</name><transactionKey>${encodeForXmlAttribute(tranKey)}</transactionKey></merchantAuthentication>
    <batchId>${encodeForXmlAttribute(bid)}</batchId>
    <sorting><orderBy>submitTimeUTC</orderBy><orderDescending>true</orderDescending></sorting>
    <paging><limit>${pageLimit}</limit><offset>${boff}</offset></paging>
</getTransactionListRequest>"""
                                gatewayCallCount++
                                ec.logger.log('info', "HOSTED_CONFIRM_GATEWAY_CALL mode=${lookupMode} operation=settled_transactions call_count=${gatewayCallCount}", null)
                                def tlNode = run(tlReq)
                                if (!ok(tlNode)) { complete = false; break }
                                def btxns = tlNode.transactions.transaction
                                collect(btxns)
                                def btotal = (tlNode.totalNumInResultSet?.text() ?: '0') as Integer
                                bscanned += btxns.size()
                                if (stopOnSuccess && haveSuccess()) { complete = false; break }
                                if (btxns.size() < pageLimit || bscanned >= btotal) break
                                if (bscanned >= hardCap) { complete = false; break }
                                boff += pageLimit
                            }
                        }
                    }
                }

                scanComplete = complete
                activity = rowsById.values().sort { a, b -> (a.submitTimeUTC ?: '') <=> (b.submitTimeUTC ?: '') } as List
                successTransIds = activity.findAll { it.cls == 'success' }.collect { it.transId }
                hasUncertain = activity.any { it.cls == 'uncertain' }

def responseNode = ec.resource.script('component://AuthorizeDotNet/service/AuthorizeDotNet/HostedHttp.groovy', 'parseHostedXml', [xmlPayload:responseString])
def rc = responseNode.messages?.resultCode?.text()
authorized = false
txnOk = false
returnedCustomerProfileId = null
responseReason = null
boundOk = false
txnInvoice = null
txnAmountStr = null
txnType = null
if ('Ok'.equalsIgnoreCase(rc ?: '')) {
    def txn = responseNode.transaction
    if (txn != null && txn.size() > 0) {
        def txnStatus = txn.transactionStatus.text()
        responseReason = txn.responseCode.text()
        txnOk = true
        authorized = (responseReason == '1') &&
            (['authorizedPendingCapture','capturedPendingSettlement','settledSuccessfully'].contains(txnStatus))
        def prof = txn.profile
        if (prof != null && prof.size() > 0) returnedCustomerProfileId = prof.customerProfileId.text()
        // Binding fields: the gateway transaction's own invoice + settled/auth amount.
        txnInvoice = txn.order?.invoiceNumber?.text()
        txnType = txn.transactionType?.text()
        txnAmountStr = (txn.settleAmount?.text() ?: txn.authAmount?.text() ?: txn.amount?.text())
    }
}

boundOk = false
try {
    def txnAmt = (txnAmountStr != null && txnAmountStr != '') ? new BigDecimal(txnAmountStr) : null
    def wantAmt = (expectedAmount != null) ? new BigDecimal(expectedAmount.toString()) : null
    // Compare at 2dp; gateway returns e.g. 50.00, order grandTotal 50.0000.
    if (txnAmt != null && wantAmt != null) {
        boundOk = (txnAmt.setScale(2, java.math.RoundingMode.HALF_UP)
                == wantAmt.setScale(2, java.math.RoundingMode.HALF_UP))
    }
} catch (Exception e) { boundOk = false }
